async Awaitable PatrolAsync()
{
    var ct = destroyCancellationToken;            // take it while the object is alive
    Patrols.Add(this);
    try
    {
        while (true)
        {
            await Awaitable.WaitForSecondsAsync(2f, ct); // destroyed: throws here
            MoveToNextPoint();
        }
    }
    catch (OperationCanceledException) { }        // cancellation isn't an error
    finally { Patrols.Remove(this); }             // cleanup runs on cancellation too
}

