async UniTask<Texture2D> LoadAsync(string url, CancellationToken ct)
{
    using var req = UnityWebRequestTexture.GetTexture(url);
    await req.SendWebRequest().WithCancellation(ct);   // a Unity operation with cancellation
    return DownloadHandlerTexture.GetContent(req);
}

